import { edit_project } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import CountryList from "@/JsonFiles/CountryList.json";
export default {
  props: {
    editMemberDialogue: Boolean,
    rowInfo: Object,
    currentData: Object
  },
  data() {
    return {
      loading: false,
      reportCheck: false,
      externalUserName: "",
      externalEmail: "",
      countrycode: "",
      contactNumber: "",
      role: "",
      memberType: "",
      countryitems: [],
      roleItems: ["Member", "Observer"],
      reportEnabled: false,
      visibleMembers: []
    };
  },
  watch: {
    editMemberDialogue: {
      async handler() {
        if (this.editMemberDialogue == true) {
          this.fetchDetails();
          this.reportEnabled = this.rowInfo.project_status_report.enabled_member_report;
          this.externalUserName = this.currentData.name;
          this.reportCheck = this.currentData.is_report == undefined ? false : this.currentData.is_report;
          this.externalEmail = this.currentData.email;
          this.role = this.currentData.role;
          this.countrycode = this.currentData.countryCode;
          this.contactNumber = this.currentData.contactNumber;
          this.memberType = this.currentData.member_type;
          this.visibleMembers = [...this.rowInfo.project_visible_members];
          const index = this.visibleMembers.findIndex(user => user.name === this.currentData.name && user.email === this.currentData.email);

          // If found, remove it
          if (index !== -1) {
            this.visibleMembers.splice(index, 1);
          }
        }
      },
      immediate: true
    }
  },
  methods: {
    is_number(evt) {
      evt = evt ? evt : window.event;
      var charCode = evt.which ? evt.which : evt.keyCode;
      if (charCode > 31 && (charCode < 48 || charCode > 57) && charCode !== 46) {
        evt.preventDefault();
      } else {
        return true;
      }
    },
    process(event) {
      if (event.type == "paste") {
        var clipboardData = event.clipboardData || window.clipboardData;
        var pastedData = clipboardData.getData("Text");
        if (isNaN(pastedData)) {
          event.preventDefault();
        } else {
          return;
        }
      }
      var keyCode = event.keyCode || event.which;
      if (keyCode >= 96 && keyCode <= 105) {
        keyCode -= 48;
      }
      var charValue = String.fromCharCode(keyCode);
      if (isNaN(parseInt(charValue)) && event.keyCode != 8) {
        event.preventDefault();
      }
    },
    fetchDetails() {
      CountryList.forEach(element => {
        this.countryitems.push({
          name: element.name + "(" + element.dial_code + ")",
          code: element.dial_code
        });
      });
    },
    close_dialog() {
      this.$emit("clicked", 0);
    },
    async delete_mutation() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.loading = true;
        try {
          let result = await API.graphql(graphqlOperation(edit_project, {
            input: {
              project_id: this.rowInfo.project_id,
              project_visible_members: this.fetch_users()
            }
          }));
          this.loading = false;
          var response = JSON.parse(result.data.edit_project);
          this.loading = false;
          if (response.Status == "SUCCESS") {
            this.$emit("successMsg", response.Message);
          } else {
            this.$emit("errorMsg", response.Message);
          }
        } catch (error) {
          this.loading = false;
          this.$emit("errorMsg", error.errors[0].message);
        }
      }
    },
    fetch_users() {
      if (this.memberType == "EXTERNAL") {
        let userUpdate = {
          contactNumber: this.contactNumber,
          countryCode: this.countrycode,
          email: this.externalEmail,
          member_type: "EXTERNAL",
          name: this.externalUserName,
          role: "",
          is_report: false
        };
